"""Dance music for the party, generated by code.

Four-on-the-floor house at 124 BPM: kick, clap, hi-hats, an off-beat bass,
stab chords and a pentatonic lead. The seed picks the key, the chord
progression and the melody, so every party sounds a little different; the
light show on the microcontroller uses the same tempo and seed.
"""

from __future__ import annotations

import numpy as np

from . import RATE

PROGRESSIONS = [
    [0, 5, 3, 4],      # i - VI - iv - v (in semitones from the minor root: see CHORDS)
    [0, 3, 5, 4],
    [0, 4, 5, 3],
    [5, 3, 0, 4],
]
# minor-key degrees -> (root offset in semitones, chord quality)
DEGREES = {0: (0, "m"), 3: (5, "m"), 4: (7, "m"), 5: (8, "M"), 6: (10, "M")}
PENTA = [0, 3, 5, 7, 10]


def _note(midi: float) -> float:
    return 440.0 * 2 ** ((midi - 69) / 12)


def _kick(n: int) -> np.ndarray:
    t = np.arange(n) / RATE
    f = 45 + 95 * np.exp(-t * 30)
    return np.sin(2 * np.pi * np.cumsum(f) / RATE) * np.exp(-t * 7)


def _noise(rng: np.random.Generator, n: int) -> np.ndarray:
    return rng.uniform(-1, 1, n)


def _clap(rng: np.random.Generator, n: int) -> np.ndarray:
    t = np.arange(n) / RATE
    x = _noise(rng, n)
    x = x - np.concatenate([[0], x[:-1]]) * 0.6      # a little high-pass
    burst = np.exp(-t * 28) + 0.5 * np.exp(-np.maximum(t - 0.012, 0) * 40) * (t > 0.012)
    return x * burst * 0.8


def _hat(rng: np.random.Generator, n: int, open_: bool = False) -> np.ndarray:
    t = np.arange(n) / RATE
    x = _noise(rng, n)
    x = x - np.concatenate([[0], x[:-1]])            # strong high-pass
    return x * np.exp(-t * (18 if open_ else 70)) * 0.35


def _saw(freq: float, n: int, detune: float = 0.0) -> np.ndarray:
    t = np.arange(n) / RATE
    ph = (t * freq * (1 + detune)) % 1.0
    return 2 * ph - 1


def _place(track: np.ndarray, sound: np.ndarray, start: int, gain: float = 1.0) -> None:
    end = min(len(track), start + len(sound))
    if start < end:
        track[start:end] += sound[: end - start] * gain


def render(seed: int, seconds: float, bpm: float = 124.0) -> np.ndarray:
    """Mono float32 samples at RATE, peak about 0.85."""
    rng = np.random.default_rng(seed)
    n = int(RATE * seconds)
    beat = RATE * 60.0 / bpm
    steps_16 = beat / 4
    out = np.zeros(n + int(RATE), dtype=np.float64)
    drums = np.zeros_like(out)
    bass = np.zeros_like(out)
    pads = np.zeros_like(out)
    lead = np.zeros_like(out)

    key = 45 + int(rng.integers(0, 7))                # A2 .. D#3
    prog = PROGRESSIONS[int(rng.integers(0, len(PROGRESSIONS)))]
    total_beats = int(seconds * bpm / 60) + 1
    kick = _kick(int(beat * 0.9))
    clap = _clap(rng, int(beat * 0.5))
    hat_c = _hat(rng, int(steps_16 * 0.9))
    hat_o = _hat(rng, int(beat * 0.45), True)
    melody = [PENTA[int(i)] for i in rng.integers(0, len(PENTA), 32)]

    for b in range(total_beats):
        start = int(b * beat)
        bar, beat_in_bar = divmod(b, 4)
        intro = bar < 2
        _place(drums, kick, start, 1.0)
        if beat_in_bar in (1, 3) and not intro:
            _place(drums, clap, start, 0.55)
        for s in range(4):
            if s == 2:
                _place(drums, hat_o, int(start + s * steps_16), 0.5)
            elif not intro or s % 2:
                _place(drums, hat_c, int(start + s * steps_16), 0.35)
        degree = prog[bar % 4]
        root_off, quality = DEGREES.get(degree, (0, "m"))
        root = key + root_off
        # off-beat bass: the classic house "pump"
        blen = int(beat * 0.45)
        f = _note(root - 12)
        bnote = (np.sin(2 * np.pi * f * np.arange(blen) / RATE) * 0.7 + _saw(f, blen) * 0.3) * \
            np.exp(-np.arange(blen) / RATE * 6)
        _place(bass, bnote, int(start + beat / 2), 0.55)
        # stab chords on the "and" of 2 and 4
        if beat_in_bar in (1, 3) and not intro:
            third = 3 if quality == "m" else 4
            clen = int(beat * 0.35)
            chord = sum(_saw(_note(root + 12 + iv), clen, d) for iv, d in ((0, 0), (third, .003), (7, -.002)))
            chord = chord * np.exp(-np.arange(clen) / RATE * 9) / 3
            _place(pads, chord, int(start + beat / 2), 0.35)
        # pentatonic lead in eighths, from bar 4
        if bar >= 4:
            for e in range(2):
                if rng.random() < 0.7:
                    m = key + 24 + melody[(b * 2 + e) % len(melody)]
                    llen = int(beat * 0.45)
                    tone = np.sign(np.sin(2 * np.pi * _note(m) * np.arange(llen) / RATE)) * 0.3 + \
                        np.sin(2 * np.pi * _note(m) * np.arange(llen) / RATE) * 0.7
                    _place(lead, tone * np.exp(-np.arange(llen) / RATE * 7), int(start + e * beat / 2), 0.18)

    # side-chain: everything except drums ducks under the kick
    duck = np.ones_like(out)
    kick_env = np.exp(-np.arange(int(beat)) / RATE * 9)
    for b in range(total_beats):
        s = int(b * beat)
        e = min(len(duck), s + len(kick_env))
        duck[s:e] = 1 - 0.6 * kick_env[: e - s]
    out = drums + (bass + pads + lead) * duck
    out = out[:n]
    fade = int(RATE * 1.2)
    out[-fade:] *= np.linspace(1, 0, fade)
    out[: int(RATE * 0.02)] *= np.linspace(0, 1, int(RATE * 0.02))
    peak = float(np.max(np.abs(out))) or 1.0
    return np.tanh(out / peak * 1.3).astype(np.float32) * 0.85
